const recordingLedger = () => {
  const balances = new Map();
  const journal = [];
  return {
    deposit(id, amount) {
      balances.set(id, (balances.get(id) ?? 0) + amount);  // working behaviour
      journal.push({ op: 'deposit', id, amount });         // recorded interaction
    },
    journal: () => [...journal],                           // test-only accessor
  };
};
